CREATE TABLE IF NOT EXISTS recipe_import_jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,url TEXT NOT NULL,context TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN ('queued','working','ready','failed','done')),result TEXT,error TEXT,recipe_id INTEGER,dismissed INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS recipe_import_jobs_owner ON recipe_import_jobs(user_id,created_at);
